options.helpers:
context.handlebars.registerHelper("priority", priority => {
  if (priority === 2) return "lead";
  if (priority === 1) return "lag";
  return "standby";
})

context.handlebars.registerHelper("state", (state) => {
  if (state === 0) return "stopped";
  if (state === 1) return "starting";
  if (state === 2) return "running";
  if (state === 3) return "stopping";
  if (state === 4) return "fault";
  return "unvailable";
})

context.handlebars.registerHelper("stateClass", (state) => {
  if (state === 0) return "stopped";
  if (state === 1) return "running";
  if (state === 2) return "running";
  if (state === 3) return "stopped";
  if (state === 4) return "error";
  return "unvailable";
})

