context.handlebars.registerHelper('alarmClass', activeAlarms => {
  if (activeAlarms === 0) return 'ok';
  if (activeAlarms === 1) return 'warn';
  return 'bad'
})

context.handlebars.registerHelper('runTime', runtime => {
  const hour = Math.floor(runtime / 60);
  const min = Math.round(runtime % 60);
  return `${hour}h ${min}m`
})

